/* Starting at startSlot, steps forward (direction >= 0) or backward (direction < 0), wrapping around, until a used pickup item slot is found; returns that slot. */ s32 findNextPickupItemSlot(s32 startSlot, s32 direction) {
    s32 maxSlot;
    s32 slot;

    maxSlot = 0x77;
    slot = startSlot;
    if (slot > maxSlot) {
        slot = -(direction < 1) & 0x76;
    }
    if (slot < 0) {
        slot = 0x76;
    }
    if (direction < 0) {
loop_5:
        if (!(isPickupItemSlotUsed(slot) & 0xFFFF)) {
            if (slot > 0) {
                slot -= 1;
            } else {
                slot = maxSlot;
            }
            goto loop_5;
        }
    } else {
        while (!(isPickupItemSlotUsed(slot) & 0xFFFF)) {
            if (slot < maxSlot) {
                slot += 1;
            } else {
                slot = 0;
            }
        }
    }
    return slot;
}
